{-# LANGUAGE TemplateHaskell #-}
-- The ZipMatchK instance of a base type, for the universe levels.
{-# OPTIONS_GHC -Wno-orphans #-}
-- | The raw syntax generated by BNFC from
-- @demo/grammar/DependentTypes/Syntax.cf@, re-exported together with the
-- helpers and the 'FreeFoilConfig' that free-foil's Template Haskell needs,
-- and the 'ZipMatchK' instance of the universe levels, which the signature
-- holds.
-- The config lives in a module of its own because a splice cannot use a
-- value defined in the same module.
module DependentTypes.Raw
  ( module DependentTypes.Syntax.Abs
  , config
  , rawVar
  , intToVarIdent
  , rawScopedTerm
  , rawScopeToTerm
  ) where

import Control.Monad.Free.Foil.TH.MkFreeFoil (FreeFoilConfig (..), FreeFoilTermConfig (..))
import Data.ZipMatchK (ZipMatchK (..), zipMatchViaEq)

import DependentTypes.Syntax.Abs

-- | Universe levels match when they are equal.
instance ZipMatchK Integer where
  zipMatchWithK = zipMatchViaEq

rawVar :: VarIdent -> Term
rawVar = Var

intToVarIdent :: Int -> VarIdent
intToVarIdent i = VarIdent ("x" <> show i)

rawScopedTerm :: Term -> ScopedTerm
rawScopedTerm = AScopedTerm

rawScopeToTerm :: ScopedTerm -> Term
rawScopeToTerm (AScopedTerm t) = t

config :: FreeFoilConfig
config = FreeFoilConfig
  { rawQuantifiedNames = []
  , freeFoilTermConfigs =
      [ FreeFoilTermConfig
          { rawIdentName = ''VarIdent
          , rawTermName = ''Term
          , rawBindingName = ''Pattern
          , rawScopeName = ''ScopedTerm
          , rawVarConName = 'Var
          , rawSubTermNames = []
          , rawSubScopeNames = []
          , intToRawIdentName = 'intToVarIdent
          , rawVarIdentToTermName = 'rawVar
          , rawTermToScopeName = 'rawScopedTerm
          , rawScopeToTermName = 'rawScopeToTerm
          } ]
  , freeFoilNameModifier = ("FF" ++)
  , freeFoilScopeNameModifier = ("FFScoped" ++)
  , freeFoilConNameModifier = ("FF" ++)
  , freeFoilConvertFromName = ("from" ++)
  , freeFoilConvertToName = ("to" ++)
  , signatureNameModifier = (++ "Sig")
  }
